    51  static void exitHandler(void)
    52  {
    53          fr_dict_free(&dict, __FILE__);
    54
    55          if (fr_dict_global_ctx_free(dict_gctx) < 0) fr_perror("fuzzer");
    56
    57          if (dl && dl->handle) {
    58                  dlclose(dl->handle);
    59                  dl->handle = NULL;
    60          }
    61          talloc_free(dl_loader);
