    64  int LLVMFuzzerInitialize(int *argc, char ***argv)
    65  {
    66          char const              *lib_dir  = getenv("FR_LIBRARY_PATH");
    67          char const              *proto    = getenv("FR_LIBRARY_FUZZ_PROTOCOL");
    68          char const              *dict_dir = getenv("FR_DICTIONARY_DIR");
    69          char                    buffer[1024];
    70
    71          if (!argc || !argv || !*argv) return -1; /* shut up clang scan */
    72
    73          /*
    74           *      Setup atexit handlers to free any thread local
    75           *      memory on exit
    76           */
    77          fr_atexit_global_setup();
    78
    79          /*
    80           *      Initialise the error stack _before_ we run any
    81           *      tests so there's no chance of the memory
    82           *      appearing as a leak the first time an error
    83           *      is generated.
    84           */
    85          fr_strerror_const("fuzz"); /* allocate the pools */
    86          fr_strerror_clear(); /* clears the message, leaves the pools */
    87
    88          /*
    89           *      Setup our own internal atexit handler
    90           */
    91          if (atexit(exitHandler)) {
    92                  fr_perror("fuzzer: Failed to register exit handler: %s", fr_syserror(errno));
    93                  fr_exit_now(EXIT_FAILURE);
    94          }
    95
    96          /*
    97           *      Get the name from the binary name of fuzzer_foo
    98           */
    99          if (!proto) {
   100                  proto = strrchr((*argv)[0], '_');
   101                  if (proto) proto++;
   102          }
   103
   104          /*
   105           *      Look for -D dir
   106           *
   107           *      If found, nuke it from the argument list.
   108           */
   109          if (!dict_dir) {
   110                  int i, j;
   111
   112                  for (i = 0; i < *argc - 1; i++) {
   113                          char *p = (*argv)[i];
   114
   115                          if ((p[0] == '-') && (p[1] == 'D')) {
   116                                  dict_dir = (*argv)[i + 1];
   117
   118                                  for (j = i + 2; j < *argc; i++, j++) {
   119                                          (*argv)[i] = (*argv)[j];
   120                                  }
   121
   122                                  *argc -= 2;
   123                                  break;
   124                          }
   125                  }
   126          }
   127
   128          if (!dict_dir) dict_dir = DICTDIR;
   129
   130          /*
   131           *      When jobs=N is specified the fuzzer spawns worker processes via
   132           *      a shell. We have removed any -D dictdir argument that were
   133           *      supplied, so we pass it to our children via the environment.
   134           */
   135          if (setenv("FR_DICTIONARY_DIR", dict_dir, 1)) {
   136                  fprintf(stderr, "Failed to set FR_DICTIONARY_DIR env variable\n");
   137                  fr_exit_now(EXIT_FAILURE);
   138          }
   139
   140          dict_gctx = fr_dict_global_ctx_init(NULL, dict_dir);
   141          if (!dict_gctx) {
   142                  fr_perror("dict_global");
   143                  fr_exit_now(EXIT_FAILURE);
   144          }
   145
   146          if (fr_dict_internal_afrom_file(&dict, FR_DICTIONARY_INTERNAL_DIR, __FILE__) < 0) {
   147                  fr_perror("fuzzer: Failed initializing internal dictionary");
   148                  fr_exit_now(EXIT_FAILURE);
   149          }
   150
   151          if (!proto) {
   152                  fr_perror("Failed to find protocol for fuzzer");
   153                  fr_exit_now(EXIT_FAILURE);
   154          }
   155
   156          dl_loader = dl_loader_init(NULL, NULL, 0, false);
   157          if (!dl_loader) {
   158                  fr_perror("fuzzer: Failed initializing library loader");
   159                  fr_exit_now(EXIT_FAILURE);
   160          }
   161          dl_search_path_prepend(dl_loader, lib_dir);
   162
   163          snprintf(buffer, sizeof(buffer), "libfreeradius-%s", proto);
   164          dl = dl_by_name(dl_loader, buffer, NULL, false);
   165          if (!dl) {
   166                  fr_perror("fuzzer: Failed loading library %s", buffer);
   167                  fr_exit_now(EXIT_FAILURE);
   168          }
   169
   170          snprintf(buffer, sizeof(buffer), "%s_tp_decode_proto", proto);
   171
   172          tp = dlsym(dl->handle, buffer);
   173          if (!tp) {
   174                  fr_perror("fuzzer: Failed finding test point %s", buffer);
   175                  fr_exit_now(EXIT_FAILURE);
   176          }
   177
   178          if (tp->test_ctx(&decode_ctx, NULL) < 0) {
   179                  fr_perror("fuzzer: Failed finding test point %s", buffer);
   180                  fr_exit_now(EXIT_FAILURE);
   181          }
   182
   183          init = true;
   184
   185          return 1;
   186  }
