   166  /** Decode the packet
   167   *
   168   */
   169  static int mod_decode(void const *instance, request_t *request, uint8_t *const data, size_t data_len)
   170  {
   171          proto_tacacs_t const    *inst = talloc_get_type_abort_const(instance, proto_tacacs_t);
   172          fr_io_track_t const     *track = talloc_get_type_abort_const(request->async->packet_ctx, fr_io_track_t);
   173          fr_io_address_t const   *address = track->address;
   174          RADCLIENT const         *client;
   175          fr_tacacs_packet_t const *pkt = (fr_tacacs_packet_t const *)data;
   176          fr_dcursor_t            cursor;
   177
   178          RHEXDUMP3(data, data_len, "proto_tacacs decode packet");
   179
   180          /*
   181           *      Set the request dictionary so that we can do
   182           *      generic->protocol attribute conversions as
   183           *      the request runs through the server.
   184           */
   185          request->dict = dict_tacacs;
   186
   187          client = address->radclient;
   188
   189          /*
   190           *      Decode the header, etc.
   191           *
   192           *      The "type = ..." loader ensures that we only get request packets
   193           */
   194          switch (pkt->hdr.type) {
   195          case FR_TAC_PLUS_AUTHEN:
   196                  if (packet_is_authen_start_request(pkt)) {
   197                          request->packet->code = FR_PACKET_TYPE_VALUE_AUTHENTICATION_START;
   198                  } else {
   199                          request->packet->code = FR_PACKET_TYPE_VALUE_AUTHENTICATION_CONTINUE;
   200                  }
   201                  break;
   202
   203                  case FR_TAC_PLUS_AUTHOR:
   204                          request->packet->code = FR_PACKET_TYPE_VALUE_AUTHORIZATION_REQUEST;
   205                          break;
   206
   207          case FR_TAC_PLUS_ACCT:
   208                  request->packet->code = FR_PACKET_TYPE_VALUE_ACCOUNTING_REQUEST;
   209                  break;
   210
   211          default:
   212                  fr_assert(0);
   213                  return -1;
   214          }
   215
   216          request->packet->id   = data[2]; // seq_no
   217          request->reply->id    = data[2]; // seq_no
   218          memcpy(request->packet->vector, &pkt->hdr.session_id, sizeof(pkt->hdr.session_id));
   219
   220          request->packet->data = talloc_memdup(request->packet, data, data_len);
   221          request->packet->data_len = data_len;
   222
   223          /*
   224           *      Note that we don't set a limit on max_attributes here.
   225           *      That MUST be set and checked in the underlying
   226           *      transport, via a call to ???
   227           */
   228          fr_dcursor_init(&cursor, &request->request_pairs);
   229          if (fr_tacacs_decode(request->request_ctx, request->packet->data, request->packet->data_len,
   230                               NULL, client->secret, talloc_array_length(client->secret) - 1,
   231                               &cursor) < 0) {
   232                  RPEDEBUG("Failed decoding packet");
   233                  return -1;
   234          }
   235
   236          /*
   237           *      Set the rest of the fields.
   238           */
   239          request->client = UNCONST(RADCLIENT *, client);
   240
   241          request->packet->socket = address->socket;
   242          fr_socket_addr_swap(&request->reply->socket, &address->socket);
   243
   244          REQUEST_VERIFY(request);
   245
   246          /*
   247           *      If we're defining a dynamic client, this packet is
   248           *      fake.  We don't have a secret, so we mash all of the
   249           *      encrypted attributes to sane (i.e. non-hurtful)
   250           *      values.
   251           */
   252          if (!client->active) {
   253                  fr_pair_t *vp;
   254
   255                  fr_assert(client->dynamic);
   256
   257                  for (vp = fr_pair_list_head(&request->request_pairs);
   258                       vp != NULL;
   259                       vp = fr_pair_list_next(&request->request_pairs, vp)) {
   260                          if (!vp->da->flags.subtype) {
   261                                  switch (vp->da->type) {
   262                                  default:
   263                                          break;
   264
   265                                  case FR_TYPE_UINT32:
   266                                          vp->vp_uint32 = 0;
   267                                          break;
   268
   269                                  case FR_TYPE_IPV4_ADDR:
   270                                          vp->vp_ipv4addr = INADDR_ANY;
   271                                          break;
   272
   273                                  case FR_TYPE_OCTETS:
   274                                          fr_pair_value_memdup(vp, (uint8_t const *) "", 1, true);
   275                                          break;
   276
   277                                  case FR_TYPE_STRING:
   278                                          fr_pair_value_strdup(vp, "");
   279                                          break;
   280                                  }
   281                          }
   282                  }
   283          }
   284
   285          if (RDEBUG_ENABLED) {
   286                  fr_pair_t *vp;
   287
   288                  RDEBUG("Received %s ID %i from %pV:%i to %pV:%i length %zu via socket %s",
   289                         fr_tacacs_packet_codes[request->packet->code],
   290                         request->packet->id,
   291                         fr_box_ipaddr(request->packet->socket.inet.src_ipaddr),
   292                         request->packet->socket.inet.src_port,
   293                         fr_box_ipaddr(request->packet->socket.inet.dst_ipaddr),
   294                         request->packet->socket.inet.dst_port,
   295                         request->packet->data_len,
   296                         request->async->listen->name);
   297
   298                  log_request_pair_list(L_DBG_LVL_1, request, NULL, &request->request_pairs, NULL);
   299
   300                  /*
   301                   *      Maybe the shared secret is wrong?
   302                   */
   303                  if (client->active &&
   304                      ((pkt->hdr.flags & FR_FLAGS_VALUE_UNENCRYPTED) == 0) &&
   305                      RDEBUG_ENABLED2 &&
   306                      ((vp = fr_pair_find_by_da(&request->request_pairs, attr_tacacs_user_name, 0)) != NULL) &&
   307                      (fr_utf8_str((uint8_t const *) vp->vp_strvalue, vp->vp_length) < 0)) {
   308                          RWDEBUG("Unprintable characters in the %s. "
   309                                  "Double-check the shared secret on the server "
   310                                  "and the TACACS+ Client!", attr_tacacs_user_name->name);
   311                  }
   312          }
   313
   314          if (!inst->io.app_io->decode) return 0;
   315
   316          /*
   317           *      Let the app_io do anything it needs to do.
   318           */
   319          return inst->io.app_io->decode(inst->io.app_io_instance, request, data, data_len);
   320  }
