   322  static ssize_t mod_encode(void const *instance, request_t *request, uint8_t *buffer, size_t buffer_len)
   323  {
   324          proto_tacacs_t const    *inst = talloc_get_type_abort_const(instance, proto_tacacs_t);
   325          fr_io_track_t           *track = talloc_get_type_abort(request->async->packet_ctx, fr_io_track_t);
   326          fr_io_address_t const   *address = track->address;
   327          ssize_t                 data_len;
   328          RADCLIENT const         *client;
   329
   330          /*
   331           *      Process layer NAK, or "Do not respond".
   332           */
   333          if ((buffer_len == 1) ||
   334              (request->reply->code == FR_PACKET_TYPE_VALUE_DO_NOT_RESPOND) ||
   335              (request->reply->code == 0) || (request->reply->code >= FR_TACACS_CODE_MAX)) {
   336                  track->do_not_respond = true;
   337                  return 1;
   338          }
   339
   340          client = address->radclient;
   341          fr_assert(client);
   342
   343          /*
   344           *      Dynamic client stuff
   345           */
   346          if (client->dynamic && !client->active) {
   347                  RADCLIENT *new_client;
   348
   349                  fr_assert(buffer_len >= sizeof(client));
   350
   351                  /*
   352                   *      Allocate the client.  If that fails, send back a NAK.
   353                   *
   354                   *      @todo - deal with NUMA zones?  Or just deal with this
   355                   *      client being in different memory.
   356                   *
   357                   *      Maybe we should create a CONF_SECTION from the client,
   358                   *      and pass *that* back to mod_write(), which can then
   359                   *      parse it to create the actual client....
   360                   */
   361                  new_client = client_afrom_request(NULL, request);
   362                  if (!new_client) {
   363                          PERROR("Failed creating new client");
   364                          buffer[0] = true;
   365                          return 1;
   366                  }
   367
   368                  memcpy(buffer, &new_client, sizeof(new_client));
   369                  return sizeof(new_client);
   370          }
   371
   372          /*
   373           *      If the app_io encodes the packet, then we don't need
   374           *      to do that.
   375           */
   376          if (inst->io.app_io->encode) {
   377                  data_len = inst->io.app_io->encode(inst->io.app_io_instance, request, buffer, buffer_len);
   378                  if (data_len > 0) return data_len;
   379          }
   380
   381          data_len = fr_tacacs_encode(&FR_DBUFF_TMP(buffer, buffer_len), request->packet->data,
   382                                      client->secret, talloc_array_length(client->secret) - 1,
   383                                      &request->reply_pairs);
   384          if (data_len < 0) {
   385                  RPEDEBUG("Failed encoding TACACS+ reply");
   386                  return -1;
   387          }
   388
   389          if (RDEBUG_ENABLED) {
   390                  RDEBUG("Sending %s ID %i from %pV:%i to %pV:%i length %zu via socket %s",
   391                         fr_tacacs_packet_codes[request->reply->code],
   392                         request->reply->id,
   393                         fr_box_ipaddr(request->reply->socket.inet.src_ipaddr),
   394                         request->reply->socket.inet.src_port,
   395                         fr_box_ipaddr(request->reply->socket.inet.dst_ipaddr),
   396                         request->reply->socket.inet.dst_port,
   397                         data_len,
   398                         request->async->listen->name);
   399
   400                  log_request_pair_list(L_DBG_LVL_1, request, NULL, &request->reply_pairs, NULL);
   401          }
   402
   403          RHEXDUMP3(buffer, data_len, "proto_tacacs encode packet");
   404
   405          return data_len;
   406  }
