   408  static int mod_priority_set(void const *instance, uint8_t const *buffer, UNUSED size_t buflen)
   409  {
   410          proto_tacacs_t const *inst = talloc_get_type_abort_const(instance, proto_tacacs_t);
   411
   412          fr_assert(buffer[1] != FR_TAC_PLUS_INVALID);
   413          fr_assert(buffer[1] < FR_TAC_PLUS_MAX);
   414
   415          /*
   416           *      Disallowed packet
   417           */
   418          if (!inst->priorities[buffer[1]]) return 0;
   419
   420          /*
